import { bindServices, observer, useService } from "@rabjs/react";

// 1. 定义 Service：属性自动 observable，方法自动 Action（无需装饰器）
class CounterService extends Service {
  count = 0;

  increment() {
    this.count += 1;
  }

  decrement() {
    this.count -= 1;
  }
}

// 2. observer 包装组件，useService 获取服务实例
