  const settings = useService(SettingsService);
  const greeting = useService(GreetingService);
  return (
    <div>
      <button onClick={() => settings.setLang("zh")}>中文</button>
      <button onClick={() => settings.setLang("en")}>English</button>
      <p>{greeting.greeting}</p>
    </div>
  );
