//   list_services({})                              -> 发现 TodoService 实例
//   execute_action({ instanceId, action: "add",    -> 调用方法，页面响应式更新
//                    args: ["来自 AI 的待办"] })
//   TodoService__clear({ instanceId, args: [] })   -> 调用 @mcpTool 独立工具
